<?php
use App\Core\Db; require_once __DIR__.'/_common.php'; require_once __DIR__.'/document_templates.php'; require_once __DIR__.'/template_style.php'; require_once __DIR__.'/template_proposal.php'; require_once __DIR__.'/template_leave.php';
$pdo=Db::pdo(); $type=isset($_GET['type'])?trim((string)$_GET['type']):'proposal'; $isLeave=($type==='leave');
$emps=$pdo?$pdo->query("SELECT id,name,department,position,email FROM employees WHERE is_active=1 ORDER BY name")->fetchAll():array();
$g=$m=array(); $vp=null; $ceo=null; foreach($emps as $e){ if($e['department']==='공무')$g[]=$e; if($e['department']==='관리')$m[]=$e; if($e['position']==='부사장'&&!$vp)$vp=$e; if(($e['position']==='대표'||$e['position']==='대표이사')&&!$ceo)$ceo=$e; }
$missing=(!$vp||!$ceo); $init=array();
?><div class="space-y-5"><div class="bg-white rounded-2xl border p-4 no-print"><div class="flex gap-2"><a href="javascript:history.back()" class="px-3 py-2 bg-gray-100 rounded">뒤로가기</a><a href="?r=approval_home" class="px-3 py-2 bg-gray-100 rounded">목록으로</a></div><div class="mt-3 text-sm text-gray-600"><?php echo $isLeave?'회사 휴가계 양식 그대로 작성합니다. 휴가구분과 기간을 입력한 뒤 결재요청을 누르세요.':'회사 기안서 양식 그대로 작성합니다. 결재라인을 선택한 뒤 결재요청을 누르세요.';?></div></div>
<form method="post" action="?r=approval_store"><input type="hidden" name="_csrf" value="<?php echo h(csrf_token());?>"><input type="hidden" name="doc_type" value="<?php echo $isLeave?'leave':'proposal';?>">
<div class="bg-white rounded-2xl border p-4 no-print mb-4"><table class="w-full text-sm"><tr><th>순서</th><th>구분</th><th>결재자</th></tr><?php if($isLeave){ ?><tr><td>1</td><td>팀장</td><td><select name="team_lead_id" class="border px-2 py-1"><?php foreach($emps as $e){?><option value="<?php echo (int)$e['id'];?>"><?php echo h($e['name']);?></option><?php }?></select></td></tr><tr><td>2</td><td>PM</td><td><select name="pm_id" class="border px-2 py-1"><?php foreach($emps as $e){?><option value="<?php echo (int)$e['id'];?>"><?php echo h($e['name']);?></option><?php }?></select></td></tr><?php } else { ?><tr><td>1</td><td>공무</td><td><select name="gongmu_id" class="border px-2 py-1"><?php foreach($g as $e){?><option value="<?php echo (int)$e['id'];?>"><?php echo h($e['name']);?></option><?php }?></select></td></tr><tr><td>2</td><td>관리</td><td><select name="manage_id" class="border px-2 py-1"><?php foreach($m as $e){?><option value="<?php echo (int)$e['id'];?>"><?php echo h($e['name']);?></option><?php }?></select></td></tr><?php }?><tr><td>3</td><td>부사장</td><td><?php echo h($vp?$vp['name']:'미등록');?></td></tr><tr><td>4</td><td>대표이사</td><td><?php echo h($ceo?$ceo['name']:'미등록');?></td></tr></table><?php if($missing){?><p class="text-red-600 mt-2">직원명부에서 부사장 또는 대표가 등록되어 있지 않습니다. 관리 메뉴에서 먼저 등록해주세요.</p><?php }?><button class="mt-3 px-4 py-2 bg-indigo-600 text-white rounded" <?php echo $missing?'disabled="disabled"':'';?>>저장/결재요청</button></div>
<?php if($isLeave){ render_approval_leave_document($init,array(), 'edit'); } else { render_approval_proposal_document($init,array(),'edit'); } ?>
</form></div>